/** UI for the unsigned local model. No signer, RPC, provider or network calls.
 * Financial-looking interactions are explicitly rehearsals; source contracts are separate.
 */
const kq=s=>document.querySelector(s),kqa=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeColor=c=>/^#[0-9a-f]{6}$/i.test(String(c))?c:'#b6e9de';
const key='idfbi.kingdom.rehearsal.1.4';let model,storageOK=true,view='sanctum',roomId=1,feed='all',lens=0,reply=0,receipt=0,sound=false,clockStamp=performance.now(),reviewAction=null,dialogRenderer=null;
let rawSaved=null;try{rawSaved=localStorage.getItem(key);if(rawSaved)model=KingdomModel.restore(JSON.parse(rawSaved));}catch(e){storageOK=false;kq('#k-storage-warning').hidden=false;}
if(!model)model=new KingdomModel();
const scene=new KingdomScene(kq('#k-scene'),()=>({identity:model.identity(),locks:model.s.locks.filter(l=>l.identity===model.s.selected),now:model.s.now}));scene.motion=model.s.settings.motion&&!matchMedia('(prefers-reduced-motion: reduce)').matches;
const state=()=>model.s,artifact=()=>model.identity(),date=t=>new Date(t*1000).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}),tiny=h=>String(h).slice(0,12)+'…'+String(h).slice(-6);
const btn=(label,action,extra='',cls='k-quiet')=>`<button class="${cls}" data-k="${action}" ${extra}>${label}</button>`;
const line=(a,b)=>`<div class="k-value-row"><span>${a}</span><b>${b}</b></div>`;
function note(message,error=false){const el=kq('#k-toast');el.textContent=message;el.style.borderColor=error?'#e3b3996a':'#d4dfc54a';el.classList.add('show');clearTimeout(note.timer);note.timer=setTimeout(()=>el.classList.remove('show'),6000);}
function syncTime(){const elapsed=Math.floor((performance.now()-clockStamp)/1000);if(elapsed>0){model.s.now+=elapsed;clockStamp+=elapsed*1000;}}
function save(){if(!storageOK)return;try{localStorage.setItem(key,JSON.stringify(model.export()));}catch{storageOK=false;kq('#k-storage-warning').hidden=false;note('Storage unavailable. Export the rehearsal to keep it.');}}
function chime(){if(!sound)return;try{const A=globalThis.AudioContext||globalThis.webkitAudioContext;chime.ctx||=new A();const c=chime.ctx;c.resume();for(let i=0;i<3;i++){const o=c.createOscillator(),g=c.createGain(),t=c.currentTime+i*.08;o.frequency.value=220*[1,1.5,2.5][i];o.type='sine';g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.014,t+.01);g.gain.exponentialRampToValueAtTime(.0001,t+1.1);o.connect(g);g.connect(c.destination);o.start(t);o.stop(t+1.2);o.onended=()=>{o.disconnect();g.disconnect();};}}catch{sound=false;}}
function update(fn,message='Local state committed. No blockchain transaction.'){syncTime();const r=fn();save();scene.flash();chime();render();note(message);return r;}
function modal(kicker,title,html,rerender=null){kq('#k-dialog-kicker').textContent=kicker;kq('#k-dialog-title').textContent=title;kq('#k-dialog-body').innerHTML=html;dialogRenderer=rerender;if(!kq('#k-dialog').open)kq('#k-dialog').showModal();}
function closeModal(){kq('#k-dialog').close();reviewAction=null;dialogRenderer=null;}
function review(title,html,fn){reviewAction=fn;modal('REVIEW / UNSIGNED LOCAL REHEARSAL',title,html+`<div class="k-warning">This commits only the local rehearsal. No wallet request, funds, deployed contract, or blockchain transaction is involved.</div><div class="k-modal-actions">${btn('CONFIRM REHEARSAL ↗','confirm','','k-primary')}${btn('Cancel','close')}</div><div id="k-review-status" class="k-modal-status" role="status"></div>`);}
function nav(v){view=v;scene.section=v;kq('#k-content').classList.toggle('sanctum',v==='sanctum');kq('#k-content').scrollTop=0;render();}
function options(selected){return ['ETH',...model.s.pools.map(p=>p.asset)].map(s=>`<option ${s===selected?'selected':''} value="${esc(s)}">${esc(s)}</option>`).join('');}
function head(eyebrow,title,description,action=''){return `<div class="k-page-head"><div><div class="k-eyebrow">${eyebrow}</div><h2>${title}</h2><p>${description}</p></div>${action?`<div class="k-actions">${action}</div>`:''}</div>`;}
function home(){const a=artifact(),locks=model.s.locks.filter(l=>l.identity===a.id);return `<section class="k-home"><div class="k-home-copy"><div class="k-eyebrow">A WORLD HELD INSIDE AN OBJECT</div><h2>The world<br>was <em>inside it.</em></h2><p>Not a picture of a kingdom.<br>An artifact with places to enter,<br>promises to inspect, and a future to unfold.</p><div class="k-actions">${btn('ENTER THE MARKETPLACE ↗','nav','data-view="market"','k-primary')}${btn('Meet the world','nav','data-view="world"','k-ghost')}</div></div><div class="k-home-coordinate">⟡ &nbsp; GENESIS / ${String(a.id).padStart(4,'0')} &nbsp; ⟡</div><div class="k-home-caption">SOLID FACETS / LIVING LIGHT<br><br>DRAG TO ORBIT · SCROLL TO APPROACH</div><article class="k-home-card"><div class="k-eyebrow">LOCAL LIVING ESTATE / #${String(a.id).padStart(4,'0')}</div><h3>${esc(a.name)}</h3><div class="k-mini-stats"><div><small>HELD BY THE ARTIFACT</small><b>${format(a.balances.ETH||0)} ETH</b></div><div><small>TIME-LOCKED CLAIMS</small><b>${locks.length.toString().padStart(2,'0')}</b></div></div>${btn('Unfold the entire estate <span>↗</span>','estate',`data-id="${a.id}"`,'k-text')}<p>Sample assets, not a live wallet. Move the timeglass to inspect scheduled unlocks.</p></article><div class="k-scene-controls">${btn('RESET VIEW','reset-scene','','k-text')}${btn(sound?'SOUND ON':'SOUND OFF','sound','','k-text')}<span>PROCEDURAL FACETS · LOCAL REHEARSAL</span></div></section>`;}
function fees(){return `<div class="k-panel"><div class="k-panel-title">The Phoenix covenant <span>V4 HOOK SOURCE</span></div><p class="k-fine">A known fee trajectory, written before the first swap. No owner can turn a dial after the pool is born.</p><svg class="k-fee-chart" viewBox="0 0 450 84" role="img" aria-label="LP fee declines from 1 percent at pool birth to 0.3 percent over 24 hours"><defs><linearGradient id="k-fee-fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#c1dfbf" stop-opacity=".18"/><stop offset="1" stop-color="#c1dfbf" stop-opacity="0"/></linearGradient></defs><path d="M8 11L342 63L444 63L444 83L8 83Z" fill="url(#k-fee-fill)"/><path d="M8 11L342 63L444 63" fill="none" stroke="#cbdabe" stroke-width="1.4"/><path d="M8 78H444" stroke="#b6d3d127"/><circle cx="8" cy="11" r="3" fill="#dbe1c8"/><circle cx="342" cy="63" r="3" fill="#dbe1c8"/></svg><div class="k-fee-labels"><span><strong>1.00%</strong> at birth</span><span><strong>0.30%</strong> at 24 hours</span></div><div class="k-rule"></div>${line('Seed liquidity','Principal remains locked')}${line('Position fees','Harvestable by the creator account')}${line('Swap attribution','Router ≠ human')}${line('Settlement','Actual v4 PoolManager calls in source')}<p class="k-fine" style="margin-top:15px">A fee schedule is not an anti-bot or MEV guarantee. The sale remains a pro-rata batch sale, <strong>not a continuous clearing auction</strong>. Contract source has not been compiled or deployed here.</p></div>`;}
function launch(){const a=artifact();return `<section class="k-workspace">${head('01 / GENESIS STUDIO','Let an idea <em>take flight.</em>','One launch creates its token and conversation. Successful settlement seeds its market and seals the promised allocations.',btn('How the hook works ↗','hook'))}<div class="k-split"><div><form id="k-launch-form" class="k-panel k-fields"><div class="k-panel-title">Create a launch <span>${esc(a.name)}</span></div><div class="k-field-pair"><label><span>Token name</span><input name="name" placeholder="Something worth bringing to life" maxlength="48" required></label><label><span>Ticker</span><input name="symbol" placeholder="PHNX" pattern="[A-Za-z][A-Za-z0-9]{1,11}" maxlength="12" required></label><label><span>Fixed supply</span><input name="supply" value="1000000" inputmode="decimal" required></label><label><span>Sale length / hours</span><input name="hours" type="number" min="1" max="720" value="24" required></label><label><span>Minimum raise / ETH</span><input name="soft" value="1" inputmode="decimal" required></label><label><span>Maximum raise / ETH</span><input name="hard" value="20" inputmode="decimal" required></label><label><span>Founder allocation / %</span><input name="founder" type="number" min="0" max="20" value="10" required></label><label><span>Raise into liquidity / %</span><input name="liquidity" type="number" min="50" max="100" value="80" required></label></div><div><div class="k-allocation"><i style="width:50%"></i><i style="width:40%"></i><i style="width:10%"></i></div><div class="k-allocation-labels"><span>PUBLIC ALLOCATION</span><span>LIQUIDITY</span><span>VESTING</span></div><p class="k-fine" style="margin-top:12px">The review computes your exact allocation. Founder tokens vest over 180 days with a 30-day cliff. Treasury surplus locks for 180 days in this rehearsal.</p></div><button class="k-primary k-full" ${a.owner!==state().actor?'disabled':''}>REVIEW LAUNCH ↗</button><p class="k-fine">No token exists on a blockchain until separately compiled, tested, and deployed. Terms in this form operate only the local model.</p></form></div><div class="k-stack">${fees()}<div><div class="k-panel-title" style="padding:4px">Your launch horizon <span>${state().sales.length} LOCAL SALES</span></div>${state().sales.length?state().sales.map(s=>`<article class="k-panel k-sale" style="margin-bottom:15px"><div class="k-eyebrow">${esc(s.status.toUpperCase())} / ${esc(s.symbol)}</div><h3>${esc(s.name)}</h3>${line('Raised',format(s.raised)+' / '+format(s.hard)+' ETH')}${line('Contribution window',date(s.closes))}<div class="k-progress" style="--progress:${Math.min(100,Number(BigInt(s.raised)*10000n/BigInt(s.hard))/100)}%"><i></i></div><div class="k-actions">${s.status==='open'&&state().now<s.closes?btn('Contribute ↗','contribute',`data-id="${s.id}"`,'k-primary')+btn('Withdraw contribution','withdraw-contribution',`data-id="${s.id}"`,'k-quiet')+btn('Rehearse closing →','close-sale-time',`data-id="${s.id}"`,'k-text'):s.status==='open'?btn('Settle launch ↗','settle',`data-id="${s.id}"`,'k-primary'):btn(s.status==='refund'?'Claim refund ↗':'Claim tokens ↗','claim',`data-id="${s.id}"`,'k-primary')}${btn('Enter conversation','open-room',`data-id="${s.room}"`,'k-text')}</div></article>`).join(''):`<div class="k-empty"><span class="k-star">✧</span><h3>A beginning, not a listing.</h3><p>After you create a local launch, contribute, rehearse its closing time, settle, and claim. Every step changes the connected model.</p></div>`}</div></div></div></section>`;}
function swap(){const a=artifact();return `<section class="k-workspace" style="max-width:980px">${head('02 / TRANSMUTATION','Change its form.<br><em>Keep your conditions.</em>','Minimum received, a deadline, and optional time-locking belong to one intent—not a chain of hopeful clicks.')}<div class="k-split"><form id="k-swap-form" class="k-panel k-fields"><div class="k-panel-title">Swap from the artifact <span>LOCAL MODEL</span></div><div class="k-field-pair"><label><span>From</span><select name="input" id="k-swap-in">${options('ETH')}</select></label><label><span>To</span><select name="output" id="k-swap-out">${options('AUR')}</select></label></div><label><span>Amount to exchange</span><input name="amount" id="k-swap-amount" value="0.1" inputmode="decimal" required></label><div id="k-quote"></div><div class="k-field-pair"><label><span>Slippage / %</span><input type="number" name="slippage" id="k-slippage" min="0.1" max="5" step="0.1" value="0.5" required></label><label><span>Lock length / days</span><input type="number" name="days" value="30" min="1" max="3650" required></label></div><label class="k-check"><input type="checkbox" name="lock" id="k-swap-lock">Send the output directly into a time lock.</label><button class="k-primary k-full" ${a.owner!==state().actor?'disabled':''}>REVIEW TRANSMUTATION ↗</button><p class="k-fine"><strong>Illustrative reserve quote, not a live v4 quote.</strong> This model does not simulate ticks, external liquidity, routing competition, or MEV.</p></form><div class="k-stack"><div class="k-panel"><div class="k-panel-title">One action, two chambers <span>SWAP → VAULT</span></div><h3 style="font:29px Georgia,serif;margin-bottom:18px">Exchange into<br>your future.</h3><p class="k-fine">With the vault option selected, received tokens never become a separate spendable balance in the intermediate state. A failed lock must revert the exchange too.</p><div class="k-rule"></div>${line('Executing identity',esc(a.name))}${line('Custodian',esc(a.owner))}${Object.entries(a.balances).map(([s,n])=>line(esc(s),format(n))).join('')}<div class="k-warning">The new Solidity market calls v4 directly. This screen is a separate local rehearsal—not a connected v4 wallet client.</div></div>${fees()}</div></div></section>`;}
function quote(){try{const q=model.quote(kq('#k-swap-in').value,kq('#k-swap-out').value,wei(kq('#k-swap-amount').value)),slip=Math.round(Number(kq('#k-slippage').value)*100),min=q.out*BigInt(10000-slip)/10000n;kq('#k-quote').innerHTML=`<div class="k-value-row"><span>Estimated output</span><b class="k-big-amount">${format(q.out,5)} <small style="font-size:12px">${esc(kq('#k-swap-out').value)}</small></b></div>${line('Minimum received',format(min,6))}${line('LP fee per hop',q.hops.map(h=>(h.fee/10000).toFixed(2)+'%').join(' → '))}${line('Path',esc(kq('#k-swap-in').value)+(q.hops.length===2?' → ETH':'')+' → '+esc(kq('#k-swap-out').value))}`;}catch(e){kq('#k-quote').textContent=e.message;}}
function lockCard(l){const projected=releasable(l,state().now+lens*86400),available=releasable(l,state().now);const pct=Number((BigInt(l.released)+projected)*10000n/BigInt(l.amount))/100;return `<article class="k-lock-card"><div class="k-panel-title"><span class="k-eyebrow">LOCK ${String(l.id).padStart(3,'0')} / ${l.linear?'LINEAR VESTING':'TIME CLIFF'}</span><span class="k-count">${available>0n?'CLAIMABLE':'SEALED'}</span></div><h3>${format(BigInt(l.amount)-BigInt(l.released))} ${esc(l.asset)}</h3><p class="k-fine">Beneficiary: ${esc(model.identity(l.identity).name)} · #${l.identity}</p><div class="k-progress" style="--progress:${pct}%"><i></i></div>${line('First release',date(l.cliff))}${line('Fully vested',date(l.end))}<div class="k-projection">${lens?'At +'+lens+' days':'At current rehearsal time'}: <b>${format(projected)} ${esc(l.asset)}</b> releasable.<br><span class="k-fine">Projection changes the view, never the release rule.</span></div><div class="k-actions">${btn('Release available ↗','release',`data-id="${l.id}" ${available===0n?'disabled':''}`,'k-ghost')}${btn('Inspect exact schedule','inspect-lock',`data-id="${l.id}"`,'k-text')}</div></article>`;}
function vault(){const a=artifact(),locks=state().locks.filter(l=>l.identity===a.id);return `<section class="k-workspace">${head('03 / THE TIMEGLASS','Promises with<br><em>a release date.</em>','View the future without rewriting the present. These are custody locks, not yield products or price predictions.',btn('Rehearsal clock ↗','clock'))}<div class="k-split"><form id="k-vault-form" class="k-panel k-fields"><div class="k-panel-title">Seal an allocation <span>#${a.id}</span></div><label><span>Asset</span><select name="asset">${Object.keys(a.balances).map(s=>`<option>${esc(s)}</option>`).join('')}</select></label><label><span>Amount to lock</span><input name="amount" value="1" inputmode="decimal" required></label><label><span>Release horizon / days</span><input name="days" type="number" min="1" max="3650" value="30" required></label><label class="k-check"><input name="linear" type="checkbox">Release continuously, rather than all at once.</label><div class="k-warning">The beneficiary is the NFT account. Selling the NFT changes who controls that account; it does not accelerate the lock.</div><button class="k-primary k-full" ${a.owner!==state().actor?'disabled':''}>REVIEW TIME LOCK ↗</button><p class="k-fine">No early withdrawal key. No yield. The release clock is separate from the read-only timeglass below.</p></form><div class="k-stack" id="k-locks">${locks.length?locks.map(lockCard).join(''):`<div class="k-empty"><span class="k-star">◈</span><h3>Nothing promised yet.</h3><p>Create a lock or send a swap directly into this vault.</p></div>`}</div></div></section>`;}
function market(){return `<section class="k-workspace">${head('04 / THE ESTATE EXCHANGE','Acquire a world.<br><em>Not just its surface.</em>','Open the contents before you acquire the container. Inspect balances, scheduled claims, custody, and the promises that survive a sale.',btn('List your artifact ↗','list','','k-primary')+btn('What transfers?','rights'))}<div class="k-market-grid">${state().identities.map(a=>{const locks=state().locks.filter(l=>l.identity===a.id),l=state().listings.find(l=>l.identity===a.id&&l.status==='listed');return `<article class="k-estate"><canvas class="k-estate-art" data-art="${a.id}" aria-label="Procedurally rendered architecture for ${esc(a.name)}"></canvas><div class="k-estate-body"><div class="k-estate-meta"><span>ESTATE / ${String(a.id).padStart(4,'0')}</span><span>${l?'IN COVENANT ESCROW':a.owner===state().actor?'YOUR ESTATE':'HELD BY '+esc(a.owner).toUpperCase()}</span></div><h3>${esc(a.name)}</h3><div class="k-estate-metrics"><span>NATIVE BALANCE<b>${format(a.balances.ETH||0)} ETH</b></span><span>LOCKED CLAIMS<b>${String(locks.length).padStart(2,'0')} scheduled</b></span></div><div class="k-rule" style="margin:17px 0 13px"></div><div class="k-estate-meta"><span>${l?'ASK / LOCAL REHEARSAL':'ONE CONTINUOUS IDENTITY'}</span><span>${l?format(l.price)+' ETH':'EPOCH '+a.epoch}</span></div>${btn('UNFOLD ESTATE <span>↗</span>','estate',`data-id="${a.id}"`,'k-ghost')}</div></article>`;}).join('')}</div><div class="k-market-bottom"><div class="k-panel"><div class="k-eyebrow">THE ANATOMY OF OWNERSHIP</div><h3 style="margin-top:13px">The vessel moves. Its promises remain.</h3><p>A buyer inherits control of the account, not the old owner’s identity, private keys, or the people in its rooms. A locked allocation remains locked. Old authority is not a souvenir.</p>${btn('Read the transfer boundary ↗','rights','','k-text')}</div><div class="k-panel"><span class="k-number">01</span><span class="k-eyebrow">CONTENTS BEFORE CONFIRMATION</span><p style="margin-top:15px">Each listing binds a manifest. The local rehearsal rejects changed contents. The Solidity exchange checks declared balance floors, child NFTs, vault records, and specified approvals—not every possible liability.</p>${btn('Inspect the current local receipt book ↗','receipts','','k-text')}</div></div></section>`;}
function estate(id){const a=model.identity(id),l=state().listings.find(l=>l.identity===a.id&&l.status==='listed'),locks=state().locks.filter(l=>l.identity===a.id);modal('LIVING ESTATE / #'+String(a.id).padStart(4,'0'),a.name,`<p>This is the whole declared estate, not just its visual asset. All values below belong to the local rehearsal.</p>${line('Current custody',l?'Exchange escrow / seller '+esc(l.seller):esc(a.owner))}${line('Authority epoch',String(a.epoch))}${Object.entries(a.balances).map(([s,n])=>line('Spendable '+esc(s),format(n))).join('')}${line('Presence user',model.userOf(id)?esc(model.userOf(id))+' until '+date(a.lease.expires):'None')}${line('Read-only timeglass',lens?'+'+lens+' days':'Now')}<div class="k-manifest-locks">${locks.map(x=>`<div><b>${format(BigInt(x.amount)-BigInt(x.released))} ${esc(x.asset)}</b> · ${x.linear?'linear vesting':'cliff lock'}<br>First release ${date(x.cliff)} · fully vested ${date(x.end)}<br>Releasable ${lens?'at +'+lens+' days':'now'}: <b>${format(releasable(x,state().now+lens*86400))} ${esc(x.asset)}</b></div>`).join('')||'<p>No referenced vault claims.</p>'}</div><div class="k-warning">Purchasing changes control, not the schedule. Room members are people, not sale inventory. Earlier authorship does not become the buyer’s authorship.</div>${l?`<div class="k-covenant-mark">LOCAL MANIFEST<br>${esc(l.manifest)}</div>${line('Ask',format(l.price)+' rehearsal ETH')}${line('Expires',date(l.expires))}<div class="k-modal-actions">${l.seller!==state().actor?btn('REVIEW WHOLE-ESTATE ACQUISITION ↗','buy',`data-id="${l.id}"`,'k-primary'):btn('Cancel listing / return estate','cancel-list',`data-id="${l.id}"`,'k-ghost')}</div>`:''}<div class="k-modal-actions">${btn('Enter this estate’s scene ↗','enter-estate',`data-id="${a.id}"`,'k-ghost')}${a.owner===state().actor?btn('Grant a temporary presence','presence',`data-id="${a.id}"`,'k-quiet'):''}${btn('View its artifact history','artifact-history',`data-id="${a.id}"`,'k-text')}</div>`,()=>estate(id));}
function eventText(e){const d=e.data;switch(e.kind){case'LAUNCHED':return `launched <strong>${esc(d.symbol)}</strong>. Its commons opened with it.`;case'SETTLED':return `settled <strong>${esc(d.symbol)}</strong>. Market born; promised allocations locked.`;case'SWAPPED':return `exchanged <strong>${format(d.amount)} ${esc(d.input)}</strong> for ${format(d.received)} ${esc(d.output)}${d.lock?' → locked in vault #'+d.lock:''}.`;case'LOCKED':return `sealed <strong>${format(d.amount)} ${esc(d.asset)}</strong> until ${date(d.end)}.`;case'ACQUIRED':return `acquired <strong>${esc(model.identity(e.identity).name)}</strong> from ${esc(d.previousCustodian)}. Earlier voices remain their own.`;case'LISTED':return `placed <strong>${esc(model.identity(e.identity).name)}</strong> into a content-bound sale.`;case'CONTRIBUTED':return `contributed ${format(d.amount)} ETH to <strong>${esc(d.symbol)}</strong>.`;case'CLAIMED':return `claimed an allocation or refund from <strong>${esc(d.symbol)}</strong>.`;case'RELEASED':return `released <strong>${format(d.amount)} ${esc(d.asset)}</strong> to its fixed beneficiary.`;case'PRESENCE':return `granted ${esc(d.user)} a temporary presence. No treasury authority.`;default:return esc(e.kind.toLowerCase().replaceAll('_',' '))+' · local artifact event.';}}
function eventCard(e){return `<article class="k-activity"><i>✧</i><div><p><strong>${esc(e.actor)}</strong> ${eventText(e)}</p><small>LOCAL REHEARSAL / #${e.seq} · ${e.identity?'ARTIFACT '+e.identity+' / EPOCH '+e.epoch:'PERSONAL ACTION'}</small>${btn('Inspect receipt ↗','receipt',`data-id="${e.seq}"`,'k-text')} ${btn('Discuss this action','discuss',`data-id="${e.seq}"`,'k-text')}</div></article>`;}
function messageCard(m){return `<article class="k-message" id="k-message-${m.id}"><span class="k-avatar">${m.identity?'✦':'◇'}</span><div><div class="k-message-head">${btn(esc(m.actor),'profile',`data-user="${esc(m.actor)}"`,'k-text')}<span>${m.identity?'ARTIFACT '+m.identity+' · CUSTODY EPOCH '+m.epoch:'PERSONAL VOICE'}</span></div>${m.reply?`<div class="k-reply-link" data-k="inspect-message" data-id="${m.reply}">↳ Reply to ${esc(state().messages.find(x=>x.id===m.reply)?.actor)} · message ${m.reply}</div>`:''}${m.receipt?`<div class="k-reply-link" data-k="receipt" data-id="${m.receipt}">✧ Discussing local activity #${m.receipt}</div>`:''}<p class="k-message-body">${esc(m.body)}</p><div class="k-message-meta">${['✧','♡','◎'].map(emoji=>btn(emoji+(m.reactions[emoji]?.length?' '+m.reactions[emoji].length:''),'reaction',`data-id="${m.id}" data-emoji="${emoji}"`,'k-reaction '+(m.reactions[emoji]?.includes(state().actor)?'active':''))).join('')}${btn('Reply','reply',`data-id="${m.id}"`,'k-text')}</div></div></article>`;}
function world(){const r=model.room(roomId),v=state().views[state().actor]||{follow:[],block:[]};let messages=state().messages.filter(m=>m.room===roomId&&!v.block.includes(m.actor));let ev=state().events.filter(e=>['LAUNCHED','SETTLED','SWAPPED','LOCKED','ACQUIRED','LISTED','CONTRIBUTED','CLAIMED','RELEASED','PRESENCE'].includes(e.kind)&&!v.block.includes(e.actor)&&(roomId===1||e.data.room===roomId||e.identity===r.identity));if(feed==='following'){messages=messages.filter(m=>v.follow.includes(m.actor));ev=ev.filter(e=>v.follow.includes(e.actor));}let items=[...(feed==='activity'?[]:messages.map(m=>({time:m.time,id:m.id,kind:'message',item:m}))),...(feed==='people'?[]:ev.map(e=>({time:e.time,id:e.seq,kind:'event',item:e})))].sort((a,b)=>a.time-b.time||a.id-b.id);return `<section class="k-world"><aside class="k-rooms"><div class="k-eyebrow">CONSTELLATIONS / ROOMS</div>${state().rooms.map(x=>`<button class="k-room ${x.id===roomId?'active':''}" data-k="open-room" data-id="${x.id}" style="--room-color:${safeColor(x.color)}"><i></i>${esc(x.name)}<small>${x.gated?'INVITE':'OPEN'}</small></button>`).join('')}<div class="k-room-separator"></div>${btn('+ Create a room','create-room','','k-text')}${btn('Personal filters ↗','filters','','k-text')}${btn('Rehearsal persona ↗','persona','','k-text')}<p class="k-fine" style="padding:7px;margin-top:15px">All example participants are fictional. This preview does not connect to other people.</p></aside><div class="k-channel"><div class="k-channel-head"><div class="k-channel-head-top"><h3>${esc(r.name)}</h3>${btn('Room details ↗','room-settings',`data-id="${r.id}"`,'k-text')}</div><p>${esc(r.topic)}</p><div class="k-feed-tabs">${[['all','Everything'],['people','People'],['activity','Activity'],['following','Following']].map(([f,label])=>btn(label,'feed',`data-feed="${f}"`,f===feed?'active':'')).join('')}</div></div><div class="k-messages" id="k-messages">${items.map(x=>x.kind==='message'?messageCard(x.item):eventCard(x.item)).join('')||'<div class="k-empty"><span class="k-star">◎</span><p>Nothing in this view yet. Your filters change your view, not the public record.</p></div>'}</div><form id="k-message-form" class="k-compose">${reply||receipt?`<div class="k-reply-banner"><span>${reply?'Reply to message #'+reply:'Discussing activity #'+receipt}</span>${btn('×','clear-reply','','k-text')}</div>`:''}<textarea name="body" placeholder="Speak into ${esc(r.name)}…" aria-label="Message text" required maxlength="1024"></textarea><div class="k-compose-bar"><span>PUBLIC TEXT · LOCAL REHEARSAL · ${r.slow}S SLOW MODE</span><button class="k-primary">SEND ↗</button></div></form></div><aside class="k-world-aside"><div class="k-eyebrow">ONE IDENTITY, MANY VOICES</div><div class="k-constellation"><span style="left:18%;top:45%"></span><span style="left:50%;top:15%"></span><span style="left:82%;top:51%"></span><span style="left:52%;top:84%"></span></div><h3>The room remembers<br>who was speaking.</h3><p>An artifact can change hands. Its earlier words retain their custodian-at-time attribution; a buyer does not inherit the author’s identity.</p><div class="k-rule"></div><div class="k-room-details">${line('Posting',r.gated?'Accepted members':'Public')}${line('Reading','Public, not private')}${line('Slow mode',r.slow+' seconds')}${line('Following',v.follow.length+(v.follow.length===1?' person':' people'))}</div><div class="k-follows">${v.follow.map(u=>btn(esc(u),'profile',`data-user="${esc(u)}"`,'k-text')).join('')}</div><div class="k-rule"></div><p>Typed claims and protocol activity are different objects. A message can discuss a receipt; it cannot manufacture a launch.</p></aside></section>`;}
function thumbs(){kqa('[data-art]').forEach(canvas=>{const a=model.identity(canvas.dataset.art),r=Object.create(KingdomScene.prototype);r.canvas=canvas;r.ctx=canvas.getContext('2d');r.w=canvas.clientWidth;r.h=canvas.clientHeight;r.dpr=Math.min(devicePixelRatio||1,1.5);canvas.width=r.w*r.dpr;canvas.height=r.h*r.dpr;r.time=a.seed*.02;r.yaw=(a.color-1)*.12;r.pitch=.03;r.zoom=.9;r.lens=lens;r.getState=()=>({identity:a,now:state().now,locks:state().locks.filter(x=>x.identity===a.id)});r.makeSky();r.ctx.setTransform(r.dpr,0,0,r.dpr,0,0);r.ctx.drawImage(r.sky,0,0);r.project=function(p){const size=this.h*.91,pers=5.8/(5.8+p[2]);return [this.w*.5+p[0]*size*pers,this.h*.71-p[1]*size*pers,p[2]];};r.faces=[];r.seed=a.seed;for(let j=0;j<34;j++){const theta=j*2.39996,rr=j?Math.sqrt(j)*.033:0;const x=Math.cos(theta)*rr,z=Math.sin(theta)*rr;const h=j===0?.6:.10+r.rand(j+23)*.35;r.crystal(x,-.1,z,j===0?.063:.018+r.rand(j+19)*.02,h,a.color,j*.31,.7);}r.crystal(0,-.14,0,.24,-.21,a.color,.6,.36);r.paintFaces();r.ctx.globalCompositeOperation='screen';r.halo(r.w*.5,r.h*.4,r.h*.55,a.color===0?'151,230,209':a.color===1?'205,181,237':'234,211,171',.12);r.ctx.globalCompositeOperation='source-over';});}
function lensPaint(){scene.lens=lens;scene.dirty=true;kq('#k-lens-readout').textContent=lens?'+'+lens+'D':'NOW';kq('#k-time-name').textContent=artifact().name.replace(/^The /,'');if(view==='vault')kq('#k-locks').innerHTML=state().locks.filter(l=>l.identity===state().selected).map(lockCard).join('');if(dialogRenderer)dialogRenderer();}
function render(){kqa('#k-tabs button').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);b.setAttribute('aria-current',b.dataset.view===view?'page':'false');});kq('#k-persona').value=state().actor;kq('#k-motion').textContent=scene.motion?'DRIFT ON':'DRIFT OFF';kq('#k-motion').setAttribute('aria-pressed',String(scene.motion));kq('#k-id-select').innerHTML=state().identities.map(a=>`<option value="${a.id}" ${a.id===state().selected?'selected':''}>#${a.id} · ${esc(a.name)}</option>`).join('');kq('#k-content').innerHTML=({sanctum:home,launch,swap,vault,market,world}[view])();kq('#k-content').classList.toggle('sanctum',view==='sanctum');scene.dirty=true;lensPaint();if(view==='swap')quote();if(view==='market')requestAnimationFrame(thumbs);if(view==='world')requestAnimationFrame(()=>{const e=kq('#k-messages');if(e)e.scrollTop=e.scrollHeight;});}
function profile(user){const v=state().views[state().actor]||{follow:[],block:[]};modal('PERSONAL FILTER / FICTIONAL PARTICIPANT',user,`<p>This profile is an example persona. Following or blocking edits your personal view—not somebody else’s ability to use public World.</p>${line('Your current persona',esc(state().actor))}${line('Following',v.follow.includes(user)?'Yes':'No')}${line('Hidden in your view',v.block.includes(user)?'Yes':'No')}<div class="k-modal-actions">${user!==state().actor?btn(v.follow.includes(user)?'Unfollow':'Follow','follow',`data-user="${esc(user)}"`,'k-ghost')+btn(v.block.includes(user)?'Restore to my view':'Remove from my view','block',`data-user="${esc(user)}"`,'k-quiet'):''}</div>`);}
function roomSettings(id){const r=model.room(id),admin=model._admin(r),m=r.members[state().actor];modal('ROOM / '+(r.gated?'MEMBER-GATED POSTING':'PUBLIC POSTING'),r.name,`<p>${esc(r.topic)}</p>${line('Reading','Always public in this storage design')}${line('Room authority',r.identity?esc(model.identity(r.identity).name):'World has no global administrator')}${line('Your posting access',model._canPost(r,state().actor)?'Allowed':'Not yet allowed')}<div class="k-warning">Removing a member prevents future posts here. It does not delete already-public text, revoke old decryption keys, or expel anyone from World.</div>${m&&!m.accepted?btn('Accept this invitation','accept',`data-id="${id}"`,'k-primary'):''}${admin?`<form id="k-room-form" data-id="${id}" class="k-fields"><label><span>Room name</span><input name="name" value="${esc(r.name)}" maxlength="48" required></label><label><span>Topic</span><textarea name="topic" maxlength="256" required>${esc(r.topic)}</textarea></label><div class="k-field-pair"><label><span>Slow mode / seconds</span><input name="slow" type="number" value="${r.slow}" min="0" max="3600" required></label><label><span>Room accent</span><input name="color" type="color" value="${esc(r.color)}" style="width:100%;height:41px;background:none;border:1px solid #adcabe30"></label></div><label class="k-check"><input type="checkbox" name="gated" ${r.gated?'checked':''}>Require accepted invitations to post.</label><button class="k-primary">SAVE ROOM RULES</button></form><div class="k-rule"></div><div class="k-actions">${btn('Invite '+(state().actor==='you'?'guest':'you'),'invite',`data-id="${id}" data-user="${state().actor==='you'?'guest':'you'}"`,'k-ghost')}${btn('Remove '+(state().actor==='you'?'guest':'you'),'remove-member',`data-id="${id}" data-user="${state().actor==='you'?'guest':'you'}"`,'k-quiet')}</div>`:''}<div class="k-rule"></div><p class="k-fine">${Object.entries(r.members).map(([u,m])=>esc(u)+': '+(m.accepted?'accepted member':'invited, not accepted')).join(' · ')||'No invitations in this room.'}</p>`);}
function boundary(){modal('BUILD BOUNDARY / NOT A DEPLOYMENT','Know which world you are in.',`<p><b>The Interior is a working local rehearsal.</b> Its amounts, personas, prices, launches, and receipts are examples operated by a deterministic browser model. They are not transactions on a blockchain.</p>${line('New interface','Procedural Canvas 2D + local model')}${line('Contract implementation','v4 adapter + hook + estate exchange + ledger source')}${line('Solidity / public chain','Not compiled; not deployed in this environment')}${line('Connected v4 client','Not implemented in this preview')}${line('Private AI / omnichain','Researched; not deployed or simulated as real')}${line('Onchain full app storage','Source included; HTML not uploaded onchain')}<p>The Organism button returns to the archived v1.3 experience. Its testnet client is not a v4 adapter. Never configure it against this new market ABI.</p><div class="k-warning">Do not use this build to custody real value. Browser tests and model checks cannot validate unexecuted Solidity, v4 accounting, or external tokens.</div><div class="k-modal-actions">${btn('Export local rehearsal','export','','k-ghost')}${btn('Import local rehearsal','import')}${btn('Rehearsal persona','persona')}${btn('Inspect receipt book','receipts')}${btn('Start a separate clean rehearsal','reset-model','','k-text')}</div>`);}
function receiptModal(id){const e=state().events.find(e=>e.seq===Number(id));if(!e)throw Error('Unknown local receipt.');modal('UNSIGNED LOCAL RECEIPT / NOT CHAIN PROOF',e.kind,`<p>Typed chat cannot mint this object. It records a local model action, but does not authenticate a wallet, verify an EVM execution, or establish finality.</p><pre>${esc(JSON.stringify(e,null,2))}</pre><div class="k-actions">${btn('Discuss this action','discuss',`data-id="${e.seq}"`,'k-ghost')}</div>`);}
function downloadRehearsal(){const url=URL.createObjectURL(new Blob([JSON.stringify(model.export(),null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='idfbi-kingdom-rehearsal-'+state().seq+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);}
const actions={
 nav:b=>{closeModal();nav(b.dataset.view);},close:closeModal,
 confirm:()=>{if(!reviewAction)return;const fn=reviewAction;try{const result=update(fn);closeModal();return result;}catch(e){const el=kq('#k-review-status');if(el)el.textContent=e.message;throw e;}},
 estate:b=>estate(Number(b.dataset.id)),
 'enter-estate':b=>{model.select(Number(b.dataset.id));closeModal();save();scene.reset();nav('sanctum');scene.flash();},
 'reset-scene':()=>scene.reset(),
 motion:()=>{scene.motion=!scene.motion;state().settings.motion=scene.motion;scene.dirty=true;save();kq('#k-motion').textContent=scene.motion?'DRIFT ON':'DRIFT OFF';kq('#k-motion').setAttribute('aria-pressed',String(scene.motion));},
 sound:()=>{sound=!sound;if(sound)chime();render();},
 boundary,
 original:()=>{closeModal();kq('#kingdom').hidden=true;document.body.classList.remove('kingdom-open');scene.visible=false;if(window.__idfbi?.renderer){window.__idfbi.renderer.motion=!!actions.savedMotion;window.__idfbi.renderer.dirty=true;}kq('#k-entry').style.display='block';},
 hook:()=>modal('V4 / DESIGN AND IMPLEMENTATION','A pool with a birth covenant.',`<p>The new Solidity hook registers each launch before initialization. It admits only the configured market at the committed initial price. Its fee declines from 1.00% to 0.30% over 24 hours; those values have no owner setter.</p>${line('Hook address permission mask','0x22c0')}${line('Enabled callbacks','beforeInitialize, beforeRemoveLiquidity, beforeSwap, afterSwap')}${line('Accounting','No hook-taken currency deltas')}${line('Attribution','Router address, never assumed end user')}<p>Seed liquidity cannot be withdrawn by the launch market; a separate zero-liquidity-change call harvests fees for the creator. The app’s custom batch sale calls the v4 adapter at settlement.</p><div class="k-warning">Written against a pinned v4 core ABI. Source not compiled or exercised in a PoolManager. This is not CCA, an audited hook, or a live pool.</div>`),
 contribute:b=>modal('LAUNCH / CONTRIBUTION','Back this beginning.',`<form id="k-contribute-form" data-id="${b.dataset.id}" class="k-fields"><p>Contribute from ${esc(artifact().name)}. Before closing, contributions can be withdrawn. A failed minimum raise enables a refund.</p><label><span>ETH contribution</span><input name="amount" value="1" inputmode="decimal" required></label><button class="k-primary">REVIEW CONTRIBUTION</button></form>`),
 'withdraw-contribution':b=>modal('LAUNCH / BEFORE CLOSING','Withdraw a contribution.',`<form id="k-withdraw-form" data-id="${b.dataset.id}" class="k-fields"><label><span>Amount / ETH</span><input name="amount" value="1" inputmode="decimal" required></label><button class="k-primary">REVIEW WITHDRAWAL</button></form>`),
 'close-sale-time':b=>{const s=model.sale(b.dataset.id);review('Rehearse the closing time.',`<p>This advances the <b>entire local rehearsal clock</b> to the end of ${esc(s.name)}. It is not the read-only timeglass and does not fast-forward any blockchain.</p>`,()=>model.advance(Math.max(1,s.closes-model.s.now+1)));},
 settle:b=>review('Settle this launch.',`<p>The minimum raise determines whether to create a market and scheduled allocations or enable contributor refunds. Settlement uses the local clock.</p>`,()=>model.settle(b.dataset.id)),
 claim:b=>review('Claim your allocation.',`<p>The connected local model checks your contribution and rejects double claims. Your beneficiary is the selected artifact.</p>`,()=>model.claim(b.dataset.id)),
 release:b=>review('Release only what is available.',`<p>Tokens are delivered to the lock’s fixed NFT-account beneficiary. The future lens cannot make an early release valid.</p>`,()=>model.release(b.dataset.id)),
 'inspect-lock':b=>{const l=state().locks.find(l=>l.id===Number(b.dataset.id));modal('EXACT LOCAL SCHEDULE','A promise, in plain numbers.',`<pre>${esc(JSON.stringify(l,null,2))}</pre><p>Amounts use 18-decimal integer units. Dates are Unix seconds. A linear lock releases proportionally; a cliff releases only at its end.</p>`);},
 clock:()=>modal('EXPLICIT REHEARSAL CLOCK','Advance the model, not the chain.',`<p>The bottom timeglass is view-only. This separate tool advances every local deadline, vesting schedule, and listing expiry.</p><form id="k-clock-form" class="k-fields"><label><span>Advance / days</span><input name="days" type="number" min="1" max="3650" value="30" required></label><button class="k-primary">REVIEW CLOCK ADVANCE</button></form>`),
 buy:b=>{const l=model.checkListing(b.dataset.id),m=l.manifest;review('Acquire '+model.identity(l.identity).name+'.',`${line('Purchase price',format(l.price)+' rehearsal ETH')}${line('Paying persona',esc(state().actor))}${line('Native wallet balance',format(state().wallets[state().actor]||0)+' rehearsal ETH')}<p>The entire declared balance and lock inventory must still match the reviewed local covenant. Ownership changes atomically; unlock dates do not.</p><div class="k-covenant-mark">${esc(m)}</div>`,()=>model.buy(l.id,m));},
 'cancel-list':b=>review('Return the estate.',`<p>The listing is cancelled and the NFT returns to its seller. Account sessions remain invalidated; history remains intact.</p>`,()=>model.cancel(b.dataset.id)),
 list:()=>modal('MARKETPLACE / COVENANT ESCROW','Declare the whole estate.',`<form id="k-list-form" class="k-fields"><label><span>Your artifact</span><select name="identity">${state().identities.filter(a=>a.owner===state().actor).map(a=>`<option value="${a.id}">${esc(a.name)}</option>`).join('')}</select></label><div class="k-field-pair"><label><span>Ask / ETH</span><input name="price" value="4" inputmode="decimal" required></label><label><span>Expires / days</span><input name="days" type="number" min="1" max="30" value="7" required></label></div><p>Escrowing the NFT suspends owner spending through its account. This local model snapshots all of its known balances and locks; the Solidity exchange verifies declared constraints, not unseen liabilities.</p><button class="k-primary">REVIEW LISTING ↗</button></form>`),
 presence:b=>modal('PRESENCE ≠ OWNERSHIP','Let someone inhabit the form.',`<p>Grant a time-limited user designation, inspired by ERC-4907. It confers no account spending, launch authority, or moderator role. Existing active use must expire before this exchange accepts a listing.</p><form id="k-presence-form" data-id="${b.dataset.id}" class="k-fields"><label><span>Rehearsal guest</span><select name="user"><option value="${state().actor==='you'?'guest':'you'}">${state().actor==='you'?'guest':'you'}</option></select></label><label><span>Duration / days</span><input name="days" value="3" type="number" min="1" max="30" required></label><button class="k-primary">REVIEW PRESENCE ↗</button></form>`),
 rights:()=>modal('THE TRANSFER BOUNDARY','What the buyer does—and does not—receive.',`<p><b>Moves with the NFT:</b> control of its account, referenced token balances and child assets held there, its role as beneficiary of existing locks, its onchain metadata, and the room-administration rights held by the account.</p><p><b>Does not become the buyer’s:</b> other people’s identities, consent, private messages, external wallet keys, historical authorship, or a promise of future AI service.</p><p><b>Does not change:</b> immutable lock schedules, the prior transaction record, or the fee covenant of an already-created pool.</p><div class="k-warning">A balance manifest does not prove there are no hidden approvals, malicious token mechanics, or outside liabilities. The source exchange checks specified allowance pairs, not every possible spender. Its safety remains unverified in an EVM.</div>`),
 'artifact-history':b=>{const es=state().events.filter(e=>e.identity===Number(b.dataset.id));modal('ARTIFACT HISTORY / LOCAL MODEL','Continuity without stolen authorship.',es.map(eventCard).join('')||'<p>No recorded actions for this estate.</p>');},
 receipts:()=>modal('LOCAL RECEIPT BOOK','The actions that made this view.',`<p>Unsigned local consistency records. These hashes do not authenticate an owner or prove a blockchain execution.</p>${state().events.slice().reverse().slice(0,30).map(e=>btn(String(e.seq).padStart(3,'0')+' / '+esc(e.kind)+' / '+tiny(e.digest),'receipt',`data-id="${e.seq}"`,'k-quiet k-full')).join('<div style="height:6px"></div>')}<div class="k-modal-actions">${btn('Export the complete rehearsal','export','','k-ghost')}</div>`),
 receipt:b=>receiptModal(b.dataset.id),
 'open-room':b=>{roomId=Number(b.dataset.id);reply=receipt=0;closeModal();nav('world');},
 feed:b=>{feed=b.dataset.feed;render();},
 profile:b=>profile(b.dataset.user),
 follow:b=>{update(()=>model.view(b.dataset.user,'follow'),'Personal following updated.');profile(b.dataset.user);},
 block:b=>{update(()=>model.view(b.dataset.user,'block'),'Your personal view changed. World was not censored.');profile(b.dataset.user);},
 reaction:b=>update(()=>model.react(Number(b.dataset.id),b.dataset.emoji),'Reaction updated locally.'),
 reply:b=>{reply=Number(b.dataset.id);receipt=0;render();kq('#k-message-form textarea').focus();},
 'clear-reply':()=>{reply=receipt=0;render();},
 discuss:b=>{receipt=Number(b.dataset.id);reply=0;closeModal();nav('world');kq('#k-message-form textarea').focus();},
 'inspect-message':b=>{const m=state().messages.find(m=>m.id===Number(b.dataset.id));modal('IMMUTABLE LOCAL MESSAGE',m.actor,`<p style="white-space:pre-wrap">${esc(m.body)}</p>${line('Authored as',m.identity?'Artifact '+m.identity:'Personal voice')}${line('Custodian at that time',esc(m.custodian))}${line('Authority epoch',String(m.epoch))}`);},
 'room-settings':b=>roomSettings(Number(b.dataset.id)),
 'create-room':()=>modal('CONSTELLATION / CREATE ROOM','Give the conversation a place.',`<form id="k-create-room-form" class="k-fields"><label><span>Room name</span><input name="name" placeholder="The glass observatory" maxlength="48" required></label><label class="k-check"><input name="gated" type="checkbox">Require invitations to post.</label><p>Reading remains public. Membership is a posting permission, never encryption.</p><button class="k-primary">CREATE LOCAL ROOM ↗</button></form>`),
 invite:b=>{update(()=>model.invite(Number(b.dataset.id),b.dataset.user),'Invitation issued. The recipient must accept.');roomSettings(Number(b.dataset.id));},
 accept:b=>{update(()=>model.accept(Number(b.dataset.id)),'Invitation accepted locally.');roomSettings(Number(b.dataset.id));},
 'remove-member':b=>{update(()=>model.remove(Number(b.dataset.id),b.dataset.user),'Future posting revoked in this room. History remains.');roomSettings(Number(b.dataset.id));},
 filters:()=>modal('YOUR VIEW / NOT GLOBAL MODERATION','Choose the voices you follow.',`<p>These example people are fictional. Add or remove them from your own view without granting or revoking global access.</p>${['you','guest','archivist','weaver'].filter(u=>u!==state().actor).map(u=>btn(u+' ↗','profile',`data-user="${u}"`,'k-quiet k-full')).join('<div style="height:10px"></div>')}`),
 persona:()=>modal('REHEARSAL PERSONA / NOT A WALLET','See the other side.',`<p>Changing this local persona is not wallet authentication. Try the guest persona to accept an invitation or buy a listed estate.</p><div class="k-modal-actions">${btn('Use persona: you','set-persona','data-user="you"','k-ghost')}${btn('Use persona: guest','set-persona','data-user="guest"','k-ghost')}</div>`),
 'set-persona':b=>{model.setActor(b.dataset.user);save();closeModal();render();note('Rehearsal persona changed. No wallet connected.');},
 export:downloadRehearsal,import:()=>kq('#k-import').click(),
 'reset-model':()=>review('Start a separate rehearsal.',`<p>Export first to keep this one. Resetting discards this local scene’s changes, not the archived organism or any blockchain history.</p>`,()=>{model=new KingdomModel();storageOK=true;kq('#k-storage-warning').hidden=true;roomId=1;lens=0;reply=receipt=0;kq('#k-time').value=0;nav('sanctum');})
};
kq('#kingdom').addEventListener('click',e=>{const b=e.target.closest('[data-k]');if(!b||b.disabled)return;e.preventDefault();try{actions[b.dataset.k]?.(b);}catch(err){note(err.message,true);}});
kq('#kingdom').addEventListener('submit',e=>{e.preventDefault();const f=e.target,d=new FormData(f);try{syncTime();switch(f.id){
 case 'k-launch-form':{const terms={name:d.get('name'),symbol:d.get('symbol').toUpperCase(),supply:wei(d.get('supply')),soft:wei(d.get('soft')),hard:wei(d.get('hard')),hours:Number(d.get('hours')),founderBps:Math.round(Number(d.get('founder'))*100),liquidityBps:Math.round(Number(d.get('liquidity'))*100)};const founder=terms.supply*BigInt(terms.founderBps)/10000n,pub=(terms.supply-founder)*10000n/BigInt(10000+terms.liquidityBps),lp=terms.supply-founder-pub;review('Launch '+terms.name+'.',`${line('Ticker',esc(terms.symbol))}${line('Fixed supply',format(terms.supply))}${line('Public allocation',format(pub))}${line('Liquidity tokens',format(lp))}${line('Founder vesting',format(founder))}${line('Raise range',format(terms.soft)+'–'+format(terms.hard)+' ETH')}${line('Contribution period',terms.hours+' hours')}<p>Token, immutable terms, and a public commons appear together in the local model. Settlement happens only after the window.</p>`,()=>model.createLaunch(terms));break;}
 case 'k-contribute-form':{const id=Number(f.dataset.id),n=wei(d.get('amount'));review('Contribute '+format(n)+' ETH.',`<p>From ${esc(artifact().name)} to ${esc(model.sale(id).name)}. The cap and contribution window are checked again at confirmation.</p>`,()=>model.contribute(id,n));break;}
 case 'k-withdraw-form':{const id=Number(f.dataset.id),n=wei(d.get('amount'));review('Withdraw '+format(n)+' ETH.',`<p>Withdrawal is available only before closing and only up to your contribution.</p>`,()=>model.withdrawContribution(id,n));break;}
 case 'k-swap-form':{const input=d.get('input'),output=d.get('output'),n=wei(d.get('amount')),q=model.quote(input,output,n),bps=Math.round(Number(d.get('slippage'))*100),min=q.out*BigInt(10000-bps)/10000n,days=d.get('lock')?Number(d.get('days')):0,deadline=state().now+1200;if(!Number.isInteger(bps)||bps<10||bps>500)throw Error('Slippage must be between 0.1% and 5%.');review(days?'Exchange directly into a promise.':'Exchange with a minimum.',`${line('Spend',format(n)+' '+esc(input))}${line('Minimum received',format(min,6)+' '+esc(output))}${line('Destination',days?'Artifact vault / '+days+' days':'Artifact spendable balance')}${line('Deadline','20 minutes of rehearsal time')}<p>This is a local reserve approximation, not a live quote from Uniswap v4. Minimum output and deadline are checked again when confirmed.</p>`,()=>model.swap(input,output,n,min,days,deadline));break;}
 case 'k-vault-form':{const asset=d.get('asset'),n=wei(d.get('amount')),days=Number(d.get('days')),linear=!!d.get('linear');review('Seal '+format(n)+' '+asset+'.',`${line('Beneficiary',esc(artifact().name))}${line('Release mode',linear?'Linear vesting':'All at the deadline')}${line('Duration',days+' days')}<p>No early release. Transferring the NFT changes control of its beneficiary account, never this schedule.</p>`,()=>model.deposit(asset,n,days,linear));break;}
 case 'k-clock-form':{const days=Number(d.get('days'));review('Advance '+days+' rehearsal days.',`<p>This changes all local deadlines. It is not a blockchain transaction or an action of the view-only timeglass.</p>`,()=>model.advance(days*86400));break;}
 case 'k-list-form':{const id=Number(d.get('identity')),price=wei(d.get('price')),days=Number(d.get('days'));model.identity(id);review('Escrow '+model.identity(id).name+'.',`${line('Ask',format(price)+' ETH')}${line('Listing lifetime',days+' days')}<p>The local covenant snapshots known balances, locks, and authority after escrow invalidates sessions. Changes to that snapshot make a purchase fail.</p><p>Actual source checks only declared constraints. Unseen liabilities are not ruled out.</p>`,()=>model.listEstate(id,price,days));break;}
 case 'k-presence-form':{const id=Number(f.dataset.id),user=d.get('user'),days=Number(d.get('days'));review('A presence, not a treasury key.',`${line('User',esc(user))}${line('Duration',days+' days')}<p>The user designation is temporary and has no spending or moderator authority.</p>`,()=>model.grantPresence(id,user,days));break;}
 case 'k-message-form':{const body=d.get('body'),rep=reply,rec=receipt;update(()=>model.post(roomId,body,rep,rec),'Message recorded in the local model. Public-text design.');reply=receipt=0;render();break;}
 case 'k-room-form':{const id=Number(f.dataset.id),values={name:d.get('name'),topic:d.get('topic'),gated:!!d.get('gated'),slow:Number(d.get('slow')),color:d.get('color')};update(()=>model.configureRoom(id,values),'Room rules updated locally.');roomSettings(id);break;}
 case 'k-create-room-form':{const r=update(()=>model.createRoom(d.get('name'),!!d.get('gated')),'Room created.');roomId=r.id;closeModal();nav('world');break;}
 }}catch(err){note(err.message,true);}});
kq('#kingdom').addEventListener('input',e=>{if(e.target.closest('#k-swap-form')&&view==='swap')quote();});
kq('#k-time').addEventListener('input',e=>{lens=Number(e.target.value);lensPaint();});
kq('#k-persona').addEventListener('change',e=>{model.setActor(e.target.value);save();render();note('Rehearsal persona changed; not wallet authentication.');});
kq('#k-id-select').addEventListener('change',e=>{model.select(Number(e.target.value));save();scene.flash();render();});
kq('#k-dialog-close').addEventListener('click',closeModal);kq('#k-dialog').addEventListener('cancel',()=>{dialogRenderer=null;reviewAction=null;});kq('#k-dialog').addEventListener('click',e=>{if(e.target===kq('#k-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
kq('#k-entry').addEventListener('click',()=>{kq('#kingdom').hidden=false;document.body.classList.add('kingdom-open');scene.visible=true;scene.dirty=true;kq('#k-entry').style.display='none';if(window.__idfbi?.renderer){actions.savedMotion=window.__idfbi.renderer.motion;window.__idfbi.renderer.motion=false;}render();});
kq('#k-import').addEventListener('change',async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>3000000)throw Error('Import exceeds 3 MB.');const restored=KingdomModel.restore(JSON.parse(await file.text()));review('Replace the open local rehearsal.',`<p>The file has an internally consistent checksum and local receipt chain. It is not owner-authenticated. Importing replaces only this rehearsal; export the current one first.</p>`,()=>{model=restored;storageOK=true;roomId=1;lens=0;reply=receipt=0;kq('#k-time').value=0;kq('#k-storage-warning').hidden=true;nav('sanctum');});}catch(err){note(err.message,true);}finally{e.target.value='';}});
addEventListener('resize',()=>{if(view==='market')requestAnimationFrame(thumbs);});
document.body.classList.add('kingdom-open');render();save();
const pauseLegacy=setInterval(()=>{if(window.__idfbi?.renderer){actions.savedMotion=window.__idfbi.renderer.motion;window.__idfbi.renderer.motion=false;clearInterval(pauseLegacy);}},100);setTimeout(()=>clearInterval(pauseLegacy),30000);
window.__kingdom={version:'1.4.0',model:()=>model,scene,view:()=>view,nav,render,lens:()=>lens,export:()=>model.export(),boundary,sourceStatus:'uncompiled; not deployed',execution:'unsigned local rehearsal'};kq('#kingdom').dataset.ready='true';
